.rotating-text p {
  display: inline-flex;
  margin: 0;
  vertical-align: top;
}
.rotating-text p .worded {
  position: absolute;
  display: flex;
  opacity: 0;
}
.rotating-text p .worded .letter {
  transform-origin: center center 25px;
}
.rotating-text p .worded .letter.out {
  transform: rotateX(90deg);
  transition: 0.32s cubic-bezier(0.6, 0, 0.7, 0.2);
}
.rotating-text p .worded .letter.in {
  transition: 0.38s ease;
}
.rotating-text p .worded .letter.behind {
  transform: rotateX(-90deg);
}
